from itertools import combinations, product
K_TYPES={(3,2,0),(2,3,0),(3,1,1),(2,2,1),(1,3,1),(2,1,2),(1,2,2),(1,1,3)}
I_TYPES={(3,2,0),(2,3,0),(2,2,1)}
assert K_TYPES=={(a,b,5-a-b) for a in range(1,4) for b in range(1,4) if 5-a-b>=0}
assert I_TYPES=={(a,b,5-a-b) for a in range(4) for b in range(4) if 0<=5-a-b and a+5-a-b<=3 and b+5-a-b<=3}
C=tuple(range(2,5));D=tuple(range(5,8));T=tuple(range(8,11))
all_pairs=list(combinations(range(11),2)); pair_index={e:i for i,e in enumerate(all_pairs)}
def edge_bit(a,b): return 1<<pair_index[tuple(sorted((a,b)))]
def pair_mask(S): return sum(edge_bit(a,b) for a,b in combinations(S,2))
def forbidden(E,S,k):
    return any((E&pair_mask(U)) in (0,pair_mask(U)) for U in combinations(S,k))
clause_checks=direct_checks=keys=0
for cc,dd,tt in product((0,1),repeat=3):
    E=edge_bit(0,1)
    E|=sum(edge_bit(0,c) for c in C)|sum(edge_bit(1,d) for d in D)
    for S,flag in ((C,cc),(D,dd),(T,tt)):
        if flag:E|=pair_mask(S)
    E|=sum(edge_bit(c,t) for c in C for t in T)|sum(edge_bit(d,t) for d in D for t in T)
    def valid_side(S):
        return not any(E&pair_mask(U)==0 for U in combinations(S,4)) and not any(E&pair_mask(U)==pair_mask(U) for U in combinations(S,5))
    if not(valid_side(C+T) and valid_side(D+T)):continue
    keys+=1; clauses=[]
    for kinds,positive in ((K_TYPES,False),(I_TYPES,True)):
        for a,b,c in kinds:
            for U,V,W in product(combinations(C,a),combinations(D,b),combinations(T,c)):
                fixed=pair_mask(U)|pair_mask(V)|pair_mask(W)|sum(edge_bit(z,t) for z in U+V for t in W)
                if (E&fixed)==(0 if positive else fixed):
                    rect=sum(1<<(C.index(z)*3+D.index(w)) for z in U for w in V)
                    clauses.append((rect,positive))
    for X in range(512):
        full=E|sum(edge_bit(z,w) for i,(z,w) in enumerate(product(C,D)) if X>>i&1)
        exact=not forbidden(full,tuple(range(11)),5)
        reduced=all((X&rect)!=0 if positive else (X&rect)!=rect for rect,positive in clauses)
        assert exact==reduced,(cc,dd,tt,X)
        direct_checks+=1
    clause_checks+=len(clauses)
assert keys==5 and direct_checks==2560
print({'toy_keys':keys,'toy_completions':direct_checks,'instantiated_clauses':clause_checks,'result':'PASS'})
